//! The four waveforms of `components/signal-trace.tsx`. That file computes them
//! once when the module loads, from a sine sampled 73 times; these are the
//! strings it produces (JavaScript `toFixed`), so the SVG is the same path.

use maud::{Markup, html};

use crate::pages::labels::Lifecycle;

/// `<SignalTrace status size="lg" />`: the trace on its instrument grid.
pub fn large(lifecycle: Lifecycle) -> Markup {
    html! {
        span class="flex w-full min-w-0 items-center gap-2 instrument-grid " {
            svg role="img" aria-label=(format!("밈 신호: {}", lifecycle.label())) viewBox="0 0 120 32" preserveAspectRatio="none" class=(format!("w-full min-w-14 shrink h-14 {}", lifecycle.stroke())) {
                line x1="0" y1="16" x2="120" y2="16" class="text-(--signal-cyan)" stroke="currentColor" stroke-width="3" opacity="0.1" {}
                line x1="0" y1="16" x2="120" y2="16" stroke="currentColor" stroke-width="0.5" opacity="0.22" {}
                polyline points=(lifecycle.trace()) pathLength="1" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke" class=[lifecycle.draws().then_some("signal-draw")] {}
                @if lifecycle.live() {
                    circle cx="120" cy="16" r="2.2" fill="currentColor" class="signal-live" {}
                }
            }
        }
    }
}

